custom.apply:
if let Some(color) = $v {
            if let Some(app) = cx.app() {
                let mut variant = gpui_component::button::ButtonCustomVariant::new(app).color(crate::color::hsla(color));
                if let Some(c) = props.custom_foreground() { variant = variant.foreground(crate::color::hsla(c)); }
                if let Some(c) = props.custom_hover() { variant = variant.hover(crate::color::hsla(c)); }
                if let Some(c) = props.custom_active() { variant = variant.active(crate::color::hsla(c)); }
                if props.custom_shadow() { variant = variant.shadow(true); }
                element = element.$m(variant);
            }
        }

rustBeforeReturn:
{
            use gpui::Styled as _;
            let mut icon = if !props.icon_svg().is_empty() {
                Some(gpui_component::Icon::default().data(props.icon_svg().as_bytes()))
            } else if props.icon_color().is_some() || props.icon_custom_size() > 0.0 {
                crate::generated::icons::parse(props.icon()).map(gpui_component::Icon::new)
            } else {
                None
            };
            if let Some(color) = props.icon_color() {
                icon = icon.map(|icon| icon.text_color(crate::color::hsla(color)));
            }
            if props.icon_custom_size() > 0.0 {
                let size = gpui::px(props.icon_custom_size() as f32);
                icon = icon.map(|icon| icon.size(size));
            }
            if let Some(icon) = icon {
                element = element.icon(icon);
            }
            if !props.icon_progress().is_nan() {
                let mut progress = gpui_component::progress::ProgressCircle::new(SharedString::from(format!("{}-progress", self.id)))
                    .value(props.icon_progress() as f32);
                if let Some(color) = props.icon_progress_color() {
                    progress = progress.color(crate::color::hsla(color));
                }
                element = element.icon(progress);
            }
            if !props.loading_icon_svg().is_empty() {
                element = element.loading_icon(gpui_component::Icon::default().data(props.loading_icon_svg().as_bytes()));
            }
        }

